package org.noxeng.coincell.cart

import java.io.BufferedReader
import java.io.InputStream

/** One FlashGBX `db_DMG.json` entry: game code (e.g. `CGB-BYTF`) and full name (e.g. "Pokemon - Version Cristal (France)"). */
data class DmgDbEntry(val gameCode: String, val name: String)

/**
 * FlashGBX's Game Boy / Game Boy Color database (assets/db_dmg.tsv, generated by tools/make_dmg_db.js), keyed like
 * FlashGBX: SHA-1 of header bytes 0x000-0x17F (RomFileDMG.py:139). Used only for a friendly default game name.
 */
class DmgDatabase(private val entries: Map<String, DmgDbEntry>) {
    val size: Int get() = entries.size

    fun lookup(header: DmgHeader): DmgDbEntry? =
        if (header.raw.size >= KEY_LEN) entries[sha1Hex(header.raw, 0, KEY_LEN)] else null

    companion object {
        const val KEY_LEN = 0x180
        val EMPTY = DmgDatabase(emptyMap())

        /** Parses the TSV: `sha1 TAB game code TAB name`; `#` lines are comments. */
        fun parse(input: InputStream): DmgDatabase {
            val map = HashMap<String, DmgDbEntry>(4096)
            input.bufferedReader(Charsets.UTF_8).use { reader: BufferedReader ->
                reader.forEachLine { line ->
                    if (line.isEmpty() || line[0] == '#') return@forEachLine
                    val f = line.split('\t', limit = 3)
                    if (f.size < 3 || f[2].isBlank()) return@forEachLine
                    map[f[0]] = DmgDbEntry(f[1], f[2])
                }
            }
            return DmgDatabase(map)
        }
    }
}
